  "INSERT INTO [Meeting] ([CouncilID], [Meeting Name], [Meeting Description], [Date], [Time Start], [Time End], [Location], [Agenda], [MinutesURL], [MeetingType], [OwnerID], [IsMultiDay], [MeetingTypeID], [IsLiveInProgress], [LiveQuorumRosterCount], [minutes_text], [minutes_published_at]) VALUES\n(1, 'September Business Meeting', 'St. Mary''s Cathedral monthly business meeting', '2026-09-15', '19:30:00', '21:00:00', 'St. Mary''s Cathedral', '', '', 1, 19, 0, 1, 0, NULL, '# Call to order\n- Opened at 7:30 PM by the Grand Knight; 24 members present.\n\n# Reports\n- The Treasurer reported the picnic closed with a surplus.\n\n# Projects\n- [x] Order replacement banners for the parish picnic\n- [ ] Seal the teak furniture on the parish patio before the rains\n- [ ] Organize the council storage room in the parish hall basement\n\n# Adjournment\n- Closed at 8:55 PM with a prayer for deceased members.', '2026-09-18 20:00:00');"
